// HasDictionary applies the HasEdge predicate on the "dictionary" edge.
func HasDictionary() predicate.DictionaryEntry {
	return predicate.DictionaryEntry(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, DictionaryTable, DictionaryColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDictionaryWith applies the HasEdge predicate on the "dictionary" edge with a given conditions (other predicates).
func HasDictionaryWith(preds ...predicate.Dictionary) predicate.DictionaryEntry {
	return predicate.DictionaryEntry(func(s *sql.Selector) {
		step := newDictionaryStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasRelations applies the HasEdge predicate on the "relations" edge.
func HasRelations() predicate.DictionaryEntry {
	return predicate.DictionaryEntry(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, RelationsTable, RelationsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRelationsWith applies the HasEdge predicate on the "relations" edge with a given conditions (other predicates).
func HasRelationsWith(preds ...predicate.DictionaryRelation) predicate.DictionaryEntry {
	return predicate.DictionaryEntry(func(s *sql.Selector) {
		step := newRelationsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.DictionaryEntry) predicate.DictionaryEntry {
	return predicate.DictionaryEntry(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.DictionaryEntry) predicate.DictionaryEntry {
	return predicate.DictionaryEntry(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.DictionaryEntry) predicate.DictionaryEntry {
	return predicate.DictionaryEntry(sql.NotPredicates(p))
}
